  ('00157280','NV06','Nguồn vốn – Lãi suất – KDVTT','Cập nhật và đề xuất triển khai các quy định của TSC về lãi suất cho vay','Đột xuất khi phát sinh','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)','Lãi suất/biểu phí được cập nhật, cài đặt chính xác, đúng thời điểm hiệu lực của HSC; không gây khiếu nại của khách hàng hoặc sai lệch thu chi',70.0,40.0,40.0),
  ('00157280','NV07','Nguồn vốn – Lãi suất – KDVTT','Theo dõi, rà soát FTP tiền vay, lãi suất tiền vay','Định kỳ','Hoàn thành và gửi/duyệt trước hạn quy định hàng tháng (theo lịch báo cáo của TSC/Chi nhánh)','Lãi suất/biểu phí được cập nhật, cài đặt chính xác, đúng thời điểm hiệu lực của HSC; không gây khiếu nại của khách hàng hoặc sai lệch thu chi',10.0,7.0,7.0),
  ('00157280','NV08','Nguồn vốn – Lãi suất – KDVTT','Kiểm soát việc tính toán, rà soát, đối chiếu cấp bù dự thu dự chi FTP định kỳ/đột xuất','Định kỳ tháng/quý/năm/đột xuất','Hoàn thành và gửi/duyệt trước hạn quy định hàng tháng (theo lịch báo cáo của TSC/Chi nhánh)','Lãi suất/biểu phí được cập nhật, cài đặt chính xác, đúng thời điểm hiệu lực của HSC; không gây khiếu nại của khách hàng hoặc sai lệch thu chi',10.0,7.0,7.0),
  ('00157280','NV09','Nguồn vốn – Lãi suất – KDVTT','Ban hành biểu phí dịch vụ tại Chi nhánh','Khi HSC có thay đổi biểu phí','Hoàn thành/cập nhật ngay trong ngày HSC ban hành thay đổi (lãi suất, biểu phí...), không để chậm áp dụng tại quầy','Lãi suất/biểu phí được cập nhật, cài đặt chính xác, đúng thời điểm hiệu lực của HSC; không gây khiếu nại của khách hàng hoặc sai lệch thu chi',100.0,40.0,70.0),
  ('00157280','NV10','Nguồn vốn – Lãi suất – KDVTT','Đề xuất chính sách phí ưu đãi cho khách hàng, trình Giám đốc/Hội đồng dịch vụ','Định kỳ 6 tháng/đột xuất','Hoàn thành đúng kỳ báo cáo/rà soát 6 tháng theo quy định','Lãi suất/biểu phí được cập nhật, cài đặt chính xác, đúng thời điểm hiệu lực của HSC; không gây khiếu nại của khách hàng hoặc sai lệch thu chi',10.0,10.0,10.0),
  ('00157280','NV11','Nguồn vốn – Lãi suất – KDVTT','Quản lý trạng thái ngoại tệ của Chi nhánh','Hàng ngày','Xử lý/hoàn thành trong ngày phát sinh, không để tồn đọng, chuyển giao đúng giờ quy định của Chi nhánh','Trạng thái ngoại hối, giao dịch ngoại tệ/phái sinh được quản lý đúng hạn mức, đúng quy định về an toàn kinh doanh ngoại hối của BIDV/NHNN',10.0,4.0,4.0),
  ('00157280','NV14','Nguồn vốn – Lãi suất – KDVTT','Đầu mối kiểm soát việc phối hợp triển khai công văn/sản phẩm liên quan đến nghiệp vụ kinh doanh vốn và tiền tệ (KDVTT)','Khi có công văn hướng dẫn của HSC','Hoàn thành/cập nhật ngay trong ngày HSC ban hành thay đổi (lãi suất, biểu phí...), không để chậm áp dụng tại quầy','Trạng thái ngoại hối, giao dịch ngoại tệ/phái sinh được quản lý đúng hạn mức, đúng quy định về an toàn kinh doanh ngoại hối của BIDV/NHNN',100.0,40.0,40.0),
  ('00157280','DT01','Đánh giá & đào tạo cán bộ','Trình, ban hành văn bản triển khai công tác đánh giá cán bộ, hướng dẫn thực hiện trên phần mềm tại đơn vị','Khi HSC ban hành mới','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)','Việc đánh giá/xếp loại cán bộ khách quan, công bằng, đúng tiêu chí, đúng quy trình trên phần mềm, không bị khiếu nại hoặc phải điều chỉnh sau khi đẩy kết quả',100.0,70.0,70.0),
  ('00157280','DT02','Đánh giá & đào tạo cán bộ','Trình ban hành mới Bộ chỉ tiêu BSC phòng, KPIs cán bộ áp dụng tại đơn vị','Khi HSC ban hành mới','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)','Việc đánh giá/xếp loại cán bộ khách quan, công bằng, đúng tiêu chí, đúng quy trình trên phần mềm, không bị khiếu nại hoặc phải điều chỉnh sau khi đẩy kết quả',100.0,70.0,70.0),
  ('00157280','DT03','Đánh giá & đào tạo cán bộ','Trình điều chỉnh, cập nhật Bộ chỉ tiêu BSC/KPIs cán bộ','Khi HSC thông báo/Chi nhánh thay đổi','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)','Việc đánh giá/xếp loại cán bộ khách quan, công bằng, đúng tiêu chí, đúng quy trình trên phần mềm, không bị khiếu nại hoặc phải điều chỉnh sau khi đẩy kết quả',10.0,10.0,10.0),
  ('00157280','DT04','Đánh giá & đào tạo cán bộ','Thực hiện quy trình đánh giá cán bộ (ĐGCB) trên phần mềm PS – kỳ Quý','Quý','Hoàn thành, trình/gửi trước thời hạn báo cáo quý theo quy định của HSC','Việc đánh giá/xếp loại cán bộ khách quan, công bằng, đúng tiêu chí, đúng quy trình trên phần mềm, không bị khiếu nại hoặc phải điều chỉnh sau khi đẩy kết quả',100.0,70.0,70.0),
  ('00157280','DT05','Đánh giá & đào tạo cán bộ','Thực hiện quy trình ĐGCB trên phần mềm PS – kỳ 6 tháng/năm','6 tháng/năm','Hoàn thành đúng kỳ báo cáo/rà soát 6 tháng theo quy định','Việc đánh giá/xếp loại cán bộ khách quan, công bằng, đúng tiêu chí, đúng quy trình trên phần mềm, không bị khiếu nại hoặc phải điều chỉnh sau khi đẩy kết quả',100.0,100.0,100.0),
  ('00157280','DT06','Đánh giá & đào tạo cán bộ','Phối hợp rà soát dữ liệu đánh giá cán bộ các vị trí tác nghiệp, TDS...','Theo kỳ đánh giá','Hoàn thành và gửi/duyệt trước hạn quy định hàng tháng (theo lịch báo cáo của TSC/Chi nhánh)','Việc đánh giá/xếp loại cán bộ khách quan, công bằng, đúng tiêu chí, đúng quy trình trên phần mềm, không bị khiếu nại hoặc phải điều chỉnh sau khi đẩy kết quả',10.0,10.0,10.0),
  ('00157280','KTC01','Công tác khác/Kho tiền','Thành viên Ban quản lý kho tiền (quản lý, kiểm soát toàn bộ tiền mặt, giấy tờ có giá) – các tháng …','Tháng ... theo phân công BQL kho tiền','Hoàn thành và gửi/duyệt trước hạn quy định hàng tháng (theo lịch báo cáo của TSC/Chi nhánh)','Tiền mặt, giấy tờ có giá trong kho được quản lý, kiểm soát an toàn tuyệt đối, đúng quy định; không xảy ra mất mát, sai lệch',7.0,4.0,4.0),
  ('00157280','KTC02','Công tác khác/Kho tiền','Tham gia các Tổ kiểm tra nội bộ, Tổ công tác khác theo phân công','Khi phát sinh','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)','Số liệu, báo cáo chính xác, khớp đúng sổ sách/hệ thống; đúng thể thức, đúng quy định của BIDV; không bị TSC/kiểm toán/thanh tra nhắc nhở hoặc yêu cầu điều chỉnh lại',10.0,10.0,10.0),
  ('00157280','KTC03','Công tác khác/Kho tiền','Tham gia công tác kiểm kê (ấn chỉ, tài sản đảm bảo, tài sản...)','Khi phát sinh','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)','Số liệu, báo cáo chính xác, khớp đúng sổ sách/hệ thống; đúng thể thức, đúng quy định của BIDV; không bị TSC/kiểm toán/thanh tra nhắc nhở hoặc yêu cầu điều chỉnh lại',4.0,4.0,7.0),
  ('00157280','KTC04','Công tác khác/Kho tiền','Công tác tham gia ý kiến (văn bản/hồ sơ) – độ phức tạp cao','Khi phát sinh','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)','Văn bản ban hành đúng thẩm quyền, đúng căn cứ pháp lý/quy định BIDV, không phải sửa đổi bổ sung nhiều lần sau khi ban hành',7.0,7.0,7.0),
  ('00157280','KTC05','Công tác khác/Kho tiền','Thực hiện các công việc khác của Phòng/nhiệm vụ khó, phức tạp theo yêu cầu của Ban Giám đốc và Lãnh đạo phòng','Khi phát sinh','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)','Số liệu, báo cáo chính xác, khớp đúng sổ sách/hệ thống; đúng thể thức, đúng quy định của BIDV; không bị TSC/kiểm toán/thanh tra nhắc nhở hoặc yêu cầu điều chỉnh lại',4.0,4.0,4.0),
  ('00157280','KTC06','Công tác khác','Kiểm soát việc Theo dõi cơ chế động lực của HSC','Khi phát sinh','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)','Tổng hợp danh sách các cơ chế thưởng của HSC chính xác',7.0,10.0,10.0),
  ('00157280','KTC07','Công tác khác','Ban hành văn bản phát động thi đua tại Chi nhánh','Khi phát sinh','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)','Tờ trình/thông báo phát động thi đua',100.0,70.0,70.0),
  ('00157280','KTC08','Công tác khác','Thực hiện khen thưởng tới các phòng nghiệp vụ','Khi phát sinh','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)','Tờ trình/thông báo khen thưởng',10.0,10.0,10.0),
  ('00157280','KTC09','Công tác khác','Theo dõi rà soát công tác gán AM RM của các phòng nghiệp vụ','Khi phát sinh','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)','Báo cáo',10.0,10.0,10.0),
  ('00157280','KTC11','Công tác khác','Công tác tham gia ý kiến có độ phức tạp rất cao','Khi phát sinh','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)',NULL,10.0,10.0,10.0),
  ('00157280','KTC12','Công tác khác','Công tác tham gia ý kiến có độ phức tạp cao','Khi phát sinh','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)',NULL,7.0,7.0,7.0),
  ('00157280','KTC13','Công tác khác','Công tác tham gia ý kiến có độ phức tạp trung bính','Khi phát sinh','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)',NULL,4.0,4.0,4.0),
  ('00157280','KTC14','Công tác khác','Công tác tham gia ý kiến có độ phức tạp thấp','Khi phát sinh','Xử lý, hoàn thành trong thời gian yêu cầu của Lãnh đạo/Trụ sở chính (thường 24-48h hoặc theo văn bản chỉ đạo cụ thể)',NULL,1.0,1.0,1.0),
  ('00157275','KHTH-01','KHTH','Phối hợp với các Phòng xây dựng KHKD của Chi nhánh, gửi HSC đúng thời hạn kỳ năm','Hàng năm','Hồ sơ KHKD năm được tổng hợp và gửi HSC đúng/trước thời hạn quy định trong lịch công tác của Trụ sở chính.','Số liệu, chỉ tiêu trong KHKD chính xác, phù hợp định hướng và năng lực kinh doanh của Chi nhánh; hồ sơ không bị HSC trả lại để chỉnh sửa, bổ sung.',100.0,100.0,100.0),
  ('00157275','KHTH-02','KHTH','Phối hợp với các Phòng xây dựng KHKD của Chi nhánh, gửi HSC đúng thời hạn kỳ quý','Hàng quý','Hồ sơ KHKD quý được gửi HSC đúng/trước thời hạn quy định của từng quý.','Chỉ tiêu quý khớp với định hướng KHKD năm đã duyệt, số liệu chính xác, không phải điều chỉnh lại sau khi gửi.',100.0,70.0,70.0),
  ('00157275','KHTH-03','KHTH','Thực hiện giao KHKD cho các phòng nghiệp vụ theo đúng tiến độ kỳ năm','Hàng năm','Hoàn thành giao chỉ tiêu KHKD năm cho các phòng nghiệp vụ trong vòng 5 ngày làm việc kể từ khi Chi nhánh nhận KHKD được HSC phê duyệt.','Chỉ tiêu giao cho từng phòng đầy đủ, khớp tổng thể với KHKD Chi nhánh đã duyệt; phân bổ hợp lý theo năng lực, địa bàn từng phòng, không phát sinh khiếu nại/điều chỉnh.',100.0,100.0,100.0),
  ('00157275','KHTH-04','KHTH','Thực hiện giao KHKD cho các phòng nghiệp vụ theo đúng tiến độ kỳ quý','Hàng quý','Hoàn thành giao chỉ tiêu KHKD quý cho các phòng nghiệp vụ trong vòng 3 ngày làm việc kể từ khi có KHKD quý được duyệt.','Chỉ tiêu giao quý phù hợp tiến độ thực hiện kế hoạch năm, chính xác, không phải điều chỉnh lại.',100.0,70.0,70.0),
  ('00157275','KHTH-05','KHTH','Tham mưu đề xuất các giải pháp điều hành thực hiện nhiệm vụ kinh doanh','Khi phát sinh','Đề xuất được xây dựng và trình Ban Giám đốc trong vòng 2-3 ngày làm việc kể từ khi phát sinh yêu cầu/vấn đề cần tham mưu.','Giải pháp có căn cứ số liệu, phân tích rõ nguyên nhân, khả thi và phù hợp thực tế kinh doanh; được Ban Giám đốc phê duyệt/thông qua.',100.0,100.0,100.0),
  ('00157275','KHTH-06','KHTH','Đo lường, phân tích, báo cáo hiệu quả kinh doanh đa chiều. Rà soát, kiểm soát, đề xuất gia tăng nguồn thu','Khi phát sinh','Báo cáo phân tích và đề xuất được hoàn thành đúng thời hạn theo yêu cầu/chỉ đạo của Ban Giám đốc.','Phân tích đa chiều, đúng trọng tâm, chỉ ra rõ nguyên nhân biến động hiệu quả kinh doanh; giải pháp/đề xuất gia tăng nguồn thu khả thi và được áp dụng vào thực tế.',70.0,70.0,70.0),
  ('00157275','KHTH-07','KHTH','Xây dựng tiêu chí, ban hành thông báo hướng dẫn xét HTNV tập thể và cá nhân tại chi nhánh','Khi phát sinh','Văn bản tiêu chí, hướng dẫn xét HTNV được ban hành trước thời điểm bắt đầu kỳ đánh giá tối thiểu 5 ngày làm việc.','Tiêu chí rõ ràng, minh bạch, phù hợp quy định của HSC và thực tế Chi nhánh; không phải sửa đổi, bổ sung trong quá trình áp dụng.',100.0,100.0,100.0),
  ('00157275','KHTH-08','KHTH','Thực hiện xét HTNV tập thể và cá nhân kỳ Năm','Hàng năm','Hoàn thành xét và công bố kết quả HTNV năm đúng thời hạn theo lịch của HSC/Chi nhánh.','Kết quả xét chính xác, công bằng, đúng tiêu chí đã ban hành; không có khiếu nại hoặc phải xét/điều chỉnh lại.',100.0,100.0,100.0),
  ('00157275','KHTH-09','KHTH','Thực hiện xét HTNV tập thể và cá nhân Quý','Hàng quý','Hoàn thành xét và công bố kết quả HTNV quý đúng thời hạn quy định của từng quý.','Kết quả xét chính xác, đúng tiêu chí, khớp số liệu HTNV thực tế; không có khiếu nại.',70.0,70.0,70.0),
  ('00157275','KHTH-15','KHTH','Thực hiện chấm điểm đánh giá HTNV chi nhánh, điểm xếp hạng chi nhánh kỳ Năm','Hàng năm','Hoàn thành chấm điểm, tổng hợp điểm xếp hạng Chi nhánh và gửi HSC đúng thời hạn kỳ năm.','Điểm số chấm chính xác, đúng phương pháp/quy định của HSC; số liệu khớp với báo cáo HTNV, không bị HSC yêu cầu rà soát lại.',100.0,100.0,100.0),
  ('00157275','KHTH-17','KHTH','Thực hiện chấm điểm đánh giá HTNV chi nhánh, điểm xếp hạng chi nhánh Đánh giá kỳ Quý','Hàng quý','Hoàn thành chấm điểm, tổng hợp điểm xếp hạng Chi nhánh và gửi HSC đúng thời hạn kỳ quý.','Điểm số chấm chính xác, khớp số liệu HTNV quý, đúng quy định; không bị yêu cầu điều chỉnh.',70.0,70.0,70.0),
  ('00157275','KHTH-19','KHTH','Phối hợp trong công tác xếp hạng phòng giao dịch kỳ năm','Hàng năm','Cung cấp số liệu, phối hợp hoàn thành xếp hạng PGD kỳ năm đúng thời hạn quy định.','Số liệu cung cấp chính xác, đầy đủ; kết quả xếp hạng phản ánh đúng thực tế hoạt động của PGD, không có khiếu nại.',70.0,70.0,70.0),
  ('00157275','KHTH-21','KHTH','Khai thác số liệu, tổng hợp lên báo cáo vinh danh phòng và cán bộ kỳ quý, năm','Hàng quý','Cung cấp số liệu, phối hợp hoàn thành xếp hạng PGD kỳ quý đúng thời hạn quy định.','Số liệu chính xác, đầy đủ, kịp thời; kết quả xếp hạng không phải điều chỉnh lại.',70.0,70.0,70.0),
  ('00157275','KHTH-25','KHTH','Báo cáo kết quả hoạt động kinh doanh Chi nhánh hàng ngày','Hàng ngày','Báo cáo được gửi trước thời điểm quy định trong ngày làm việc kế tiếp (theo quy định nội bộ về báo cáo ngày).','Số liệu khớp đúng với hệ thống nguồn (core banking/báo cáo quản trị); không phải đính chính, báo cáo lại.',10.0,10.0,10.0),
  ('00157275','KHTH-26','KHTH','Báo cáo kết quả hoạt động kinh doanh Chi nhánh hàng tháng','Hàng tháng','Báo cáo được gửi đúng/trước hạn quy định của tháng (thường trong 2-3 ngày làm việc đầu tháng sau).','Số liệu chính xác, đầy đủ nội dung theo mẫu quy định, khớp với báo cáo ngày lũy kế trong tháng; không phải điều chỉnh lại.',70.0,70.0,70.0),
  ('00157275','KHTH-27','KHTH','Báo cáo kết quả hoạt động kinh doanh Chi nhánh hàng quý/6 tháng/năm','Hàng quý','Báo cáo được gửi đúng thời hạn quy định của từng kỳ (quý/6 tháng/năm).','Số liệu chính xác, đầy đủ, có phân tích đánh giá kèm theo; khớp số liệu giữa các kỳ báo cáo, không phải báo cáo lại.',100.0,100.0,100.0),
  ('00157275','KHTH-28','KHTH','Báo cáo tình hình hoạt động của các phòng nghiệp vụ hàng tháng','Hàng tháng','Tổng hợp và gửi báo cáo đúng hạn quy định hàng tháng.','Nội dung phản ánh đầy đủ, chính xác tình hình hoạt động từng phòng nghiệp vụ; số liệu khớp với báo cáo KQKD tháng.',40.0,40.0,40.0),
  ('00157275','KHTH-29','KHTH','Báo cáo đột xuất theo yêu cầu của Lãnh đạo Chi nhánh, Trụ sở chính có Độ phức tạp cao','Khi phát sinh','Hoàn thành và trình báo cáo trong vòng tối đa 3 ngày làm việc kể từ khi nhận yêu cầu.','Nội dung đáp ứng đầy đủ yêu cầu, số liệu chính xác; không phải chỉnh sửa, bổ sung nhiều lần.',70.0,70.0,70.0),
  ('00157275','KHTH-30','KHTH','Báo cáo đột xuất theo yêu cầu của Lãnh đạo Chi nhánh, Trụ sở chính có Độ phức tạp trung bình','Khi phát sinh','Hoàn thành và trình báo cáo trong vòng tối đa 2 ngày làm việc kể từ khi nhận yêu cầu.','Nội dung đầy đủ, chính xác theo yêu cầu; không phải chỉnh sửa lại.',40.0,40.0,40.0),
  ('00157275','KHTH-31','KHTH','Báo cáo đột xuất theo yêu cầu của Lãnh đạo Chi nhánh, Trụ sở chính có Độ phức tạp thấp','Khi phát sinh','Hoàn thành và trình báo cáo trong vòng 1 ngày làm việc kể từ khi nhận yêu cầu.','Nội dung đáp ứng đúng yêu cầu, số liệu chính xác, không có sai sót.',10.0,10.0,10.0),
  ('00157275','KHTH-32','KHTH','Báo cáo ngoại ngành có Độ phức tạp cao','Khi phát sinh','Hoàn thành và gửi báo cáo trong vòng tối đa 3 ngày làm việc kể từ khi nhận yêu cầu.','Nội dung, số liệu đầy đủ, chính xác, đúng yêu cầu; không bị trả lại yêu cầu bổ sung.',70.0,70.0,70.0),
  ('00157275','KHTH-33','KHTH','Báo cáo ngoại ngành có Độ phức tạp trung bình','Khi phát sinh','Hoàn thành và gửi báo cáo trong vòng tối đa 2 ngày làm việc kể từ khi nhận yêu cầu.','Nội dung, số liệu đầy đủ, chính xác theo yêu cầu.',40.0,40.0,40.0),
  ('00157275','KHTH-34','KHTH','Báo cáo ngoại ngành có Độ phức tạp thấp','Khi phát sinh','Hoàn thành và gửi báo cáo trong vòng 1 ngày làm việc kể từ khi nhận yêu cầu.','Nội dung, số liệu đầy đủ, chính xác, không có sai sót.',10.0,10.0,10.0),
  ('00157275','KHTH-35','KHTH','Trình, ban hành văn bản triển khai công tác đánh giá cán bộ, hướng dẫn thực hiện trên PM tại đơn vị','Khi phát sinh','Văn bản được trình, ban hành trước khi kỳ đánh giá bắt đầu tối thiểu 5 ngày làm việc.','Nội dung hướng dẫn đầy đủ, rõ ràng, đúng quy định của HSC; dễ thực hiện trên hệ thống PM, không phải sửa đổi, bổ sung nhiều lần.',100.0,70.0,70.0),
  ('00157275','KHTH-36','KHTH','Trình ban hành mới Bộ chỉ tiêu BSC phòng, KPIs cán bộ áp dụng tại đơn vị','Khi phát sinh','Bộ chỉ tiêu được xây dựng, trình ban hành đúng thời hạn theo kế hoạch/chỉ đạo của HSC và Chi nhánh.','Chỉ tiêu BSC/KPIs xây dựng phù hợp với KHKD, chức năng nhiệm vụ từng vị trí; được phê duyệt và áp dụng ổn định, không phải điều chỉnh nhiều lần trong kỳ áp dụng.',100.0,70.0,70.0),
  ('00157275','KHTH-37','KHTH','Trình điều chỉnh, cập nhật Bộ chỉ tiêu BSC phòng, KPIs cán bộ áp dụng tại đơn vị','Khi phát sinh','Hoàn thành trình điều chỉnh, cập nhật trong vòng 3-5 ngày làm việc kể từ khi có căn cứ điều chỉnh.','Nội dung điều chỉnh có căn cứ hợp lý, phù hợp thực tế phát sinh; được phê duyệt ngay lần trình đầu.',10.0,10.0,10.0),
  ('00157275','KHTH-38','KHTH','Thực hiện quy trình ĐGCB trên PS kỳ Quý','Hàng quý','Hoàn thành quy trình đánh giá cán bộ trên hệ thống PS đúng thời hạn quy định của kỳ quý.','Dữ liệu đánh giá đầy đủ, chính xác, khớp đúng thực tế thực hiện nhiệm vụ của cán bộ; không phải chỉnh sửa lại trên hệ thống.',100.0,70.0,70.0),
  ('00157275','KHTH-39','KHTH','Thực hiện quy trình ĐGCB trên PS kỳ 6 tháng/năm','Bán niên','Hoàn thành quy trình đánh giá cán bộ trên hệ thống PS đúng thời hạn quy định của kỳ 6 tháng/năm.','Dữ liệu đánh giá đầy đủ, chính xác, phản ánh đúng kết quả thực hiện nhiệm vụ; không phải chỉnh sửa lại.',100.0,100.0,100.0),
  ('00157275','KHTH-40','KHTH','Phối hợp rà soát dữ liệu đánh giá cán bộ các vị trí tác nghiệp, TDS...','Hàng quý','Hoàn thành rà soát và phản hồi dữ liệu đúng thời hạn quy định trong quý.','Dữ liệu rà soát chính xác, đầy đủ; phát hiện và xử lý kịp thời các sai lệch, chênh lệch dữ liệu giữa hệ thống và thực tế.',10.0,10.0,10.0),
  ('00157275','KHTH-41','KHTH','Tổng hợp nội dung trình phê duyệt kết quả TĐ hàng quý/6 tháng/năm','Khi phát sinh','Tổng hợp và trình phê duyệt kết quả thi đua đúng thời hạn quy định của từng kỳ (quý/6 tháng/năm).','Nội dung tổng hợp đầy đủ, chính xác, khớp với số liệu HTNV/xét thi đua; được phê duyệt ngay lần trình đầu, không phải chỉnh sửa lại.',100.0,100.0,100.0),
  ('00157275','KHTH-42','KHTH','Theo dõi cơ chế động lực của HSC','Hàng quý','Cập nhật, tổng hợp thông tin về cơ chế động lực đúng thời hạn theo quý.','Thông tin cập nhật đầy đủ, chính xác, kịp thời; được áp dụng đúng cho Chi nhánh, không bỏ sót cơ chế mới ban hành.',7.0,10.0,10.0),
  ('00157275','KHTH-43','KHTH','Thực hiện khen thưởng tới các phòng nghiệp vụ','Hàng quý','Hoàn thành xét, thực hiện khen thưởng đúng thời hạn trong kỳ quý theo kế hoạch/quy định.','Khen thưởng đúng đối tượng, đúng tiêu chí đã ban hành; không có khiếu nại hoặc phải điều chỉnh lại kết quả.',10.0,10.0,10.0),
  ('00157275','KHTH-44','KHTH','Theo dõi rà soát công tác gán AM RM của các phòng nghiệp vụ','Hàng tuần','Hoàn thành rà soát, cập nhật thông tin gán AM/RM đúng hạn theo tuần.','Dữ liệu gán AM/RM chính xác, cập nhật kịp thời theo biến động thực tế; không có sai sót, trùng lặp hoặc bỏ sót khách hàng.',10.0,10.0,10.0),
  ('00157275','KHTH-45','KHTH','Công tác tham gia ý kiến có Độ phức tạp rất cao','Khi phát sinh','Ý kiến tham gia được hoàn thành, phản hồi trong vòng tối đa 5 ngày làm việc kể từ khi nhận yêu cầu.','Ý kiến có căn cứ, phân tích đầy đủ các khía cạnh liên quan; được đơn vị đề nghị chấp thuận, không phải bổ sung/chỉnh sửa nhiều lần.',10.0,10.0,10.0),
  ('00157275','KHTH-46','KHTH','Công tác tham gia ý kiến có Độ phức tạp cao','Khi phát sinh','Ý kiến tham gia được hoàn thành, phản hồi trong vòng tối đa 3 ngày làm việc kể từ khi nhận yêu cầu.','Ý kiến có căn cứ, đầy đủ nội dung theo yêu cầu; không phải bổ sung, chỉnh sửa nhiều lần.',7.0,7.0,7.0),
  ('00157275','KHTH-47','KHTH','Công tác tham gia ý kiến có Độ phức tạp trung bình','Khi phát sinh','Ý kiến tham gia được hoàn thành, phản hồi trong vòng tối đa 2 ngày làm việc kể từ khi nhận yêu cầu.','Ý kiến đầy đủ, chính xác, đáp ứng đúng yêu cầu.',4.0,4.0,4.0),
  ('00157275','KHTH-48','KHTH','Công tác tham gia ý kiến có Độ phức tạp thấp','Khi phát sinh','Ý kiến tham gia được hoàn thành, phản hồi trong vòng 1 ngày làm việc kể từ khi nhận yêu cầu.','Ý kiến đúng, đầy đủ nội dung theo yêu cầu, không có sai sót.',1.0,1.0,1.0),
  ('00157275','KHTH-49','KHTH','Công tác khác có Độ phức tạp rất cao','Khi phát sinh','Hoàn thành công việc trong vòng tối đa 5 ngày làm việc kể từ khi phát sinh/được giao.','Kết quả công việc đáp ứng đầy đủ, đúng yêu cầu; không phải làm lại hoặc bổ sung nhiều lần.',10.0,10.0,10.0),
  ('00157275','KHTH-50','KHTH','Công tác khác có Độ phức tạp cao','Khi phát sinh','Hoàn thành công việc trong vòng tối đa 3 ngày làm việc kể từ khi phát sinh/được giao.','Kết quả công việc đầy đủ, chính xác theo yêu cầu; không phải làm lại.',7.0,7.0,7.0),
  ('00157275','KHTH-51','KHTH','Công tác khác có Độ phức tạp trung bình','Khi phát sinh','Hoàn thành công việc trong vòng tối đa 2 ngày làm việc kể từ khi phát sinh/được giao.','Kết quả công việc đầy đủ, chính xác, đáp ứng yêu cầu.',4.0,4.0,4.0),
  ('00157275','KHTH-52','KHTH','Công tác khác có Độ phức tạp thấp','Khi phát sinh','Hoàn thành công việc trong vòng 1 ngày làm việc kể từ khi phát sinh/được giao.','Kết quả công việc đúng yêu cầu, không có sai sót.',1.0,1.0,1.0),
  ('00157275','KHTH-53','KHTH','Thực hiện các thủ tục trong công tác mạng lưới tại đơn vị theo phân công','Khi phát sinh',NULL,NULL,7.0,10.0,10.0),
