  ('00169422','TCHC-11','TCHC','Theo dõi quản lý TS,CCLĐ theo đúng quy định, đảm bảo cân đối giữa sổ sách và thực tế','Thường xuyên',NULL,NULL,4.0,7.0,4.0),
