  ('00169422','TCHC-14','TCHC','Thực hiện các báo cáo theo yêu cầu của lãnh đạo','Theo yêu cầu lãnh đạo',NULL,NULL,7.0,7.0,7.0),
  ('00169422','TCHC-16','TCHC','Thực hiện các thủ tục thanh toán các chi phí liên quan tới thuê mua TS','Trước ngày cuối tháng hoặc theo yêu cầu phê duyệt của lãnh đạo',NULL,NULL,7.0,7.0,7.0),
