  ('00169422','TCHC-48','TCHC','Triển khai công tác PCCC tại chi nhánh (diễn tập, đào tạo, truyền thông, quán triệt…tới các tập thể và cá nhân thuộc Chi nhánh)','Theo kế hoạch',NULL,NULL,7.0,7.0,10.0),
