  ('00169422','TCHC-51','TCHC','Tổ chức thực hiện hoặc phối hợp thực hiện công tác an ninh quốc phòng, dân quân tự vệ, quân nhân tại đơn vị và các báo cáo liên quan.','Theo yêu cầu của cơ quan quân đội',NULL,NULL,7.0,7.0,7.0),
