  ('00169422','TCHC-53','TCHC','Quản lý và sử dụng con dấu của cơ quan theo đúng quy định (có sổ theo dõi bàn giao, sử dụng con dấu chính xác, đúng thẩm quyền, đúng văn bản...)','Ngay khi có yêu cầu',NULL,NULL,10.0,4.0,1.0),
  ('00169422','TCHC-54','TCHC','Đầu mối tiếp nhận Văn bản đi, Văn bản đến (bao gồm cả thư bảo lãnh) và mở sổ theo dõi đối với các loại văn bản trên','Trong ngày',NULL,NULL,7.0,4.0,4.0),
  ('00169422','TCHC-55','TCHC','Thực hiện các thủ tục chuyển phát văn bản đến đúng nơi quy định (trên VPĐT, dịch vụ chuyển phát, trình lãnh đạo phê duyệt...)','Trong ngày hoặc theo yêu cầu',NULL,NULL,10.0,4.0,4.0),
  ('00169422','TCHC-56','TCHC','Đầu mối tiếp nhận thư, chuyển phát nhanh từ các đơn vị dịch vụ và chuyển đến đúng nơi theo yêu cầu.','Trong ngày',NULL,NULL,7.0,4.0,4.0),
  ('00169422','TCHC-57','TCHC','Lưu hồ sơ, văn bản theo quy định','Trong ngày',NULL,NULL,7.0,4.0,4.0),
