  ('00169422','TCHC-59','TCHC','Thực hiện lái xe an toàn trong quá trình vận chuyển (an toàn giao thông, an toàn cho người và tài sản)','Thường xuyên',NULL,NULL,7.0,7.0,7.0),
  ('00169422','TCHC-60','TCHC','Tuân thủ về quy định quản lý và sử dụng tài sản lưu động của đơn vị (tiết kiệm, hiệu quả, đúng mục đích...)','Thường xuyên',NULL,NULL,7.0,4.0,7.0),
  ('00169422','TCHC-61','TCHC','Thực hiện thanh toán các chi phí liên quan tới công tác vận chuyển','Tháng',NULL,NULL,4.0,7.0,7.0),
  ('00169422','TCHC-62','TCHC','Lưu hồ sơ theo quy định','Tháng',NULL,NULL,4.0,4.0,4.0),
  ('00169422','TCHC-63','TCHC','Theo dõi và phân công công tác, ủy quyền của Ban lãnh đạo','Kịp thời',NULL,NULL,7.0,7.0,4.0),
  ('00169422','TCHC-64','TCHC','Thực hiện công tác hậu cần khi lãnh đạo tiếp khách đối nội, đối ngoại….','Kịp thời',NULL,NULL,7.0,4.0,4.0),
  ('00169422','TCHC-65','TCHC','Nghiên cứu và xây dựng quy trình, quy định nội bộ','Theo yêu cầu',NULL,NULL,70.0,100.0,100.0),
  ('00183881','KHTH-01','KHTH','Phối hợp với các Phòng xây dựng KHKD của Chi nhánh, gửi HSC đúng thời hạn kỳ năm','Hàng năm','Hồ sơ KHKD năm được tổng hợp và gửi HSC đúng/trước thời hạn quy định trong lịch công tác của Trụ sở chính.','Số liệu, chỉ tiêu trong KHKD chính xác, phù hợp định hướng và năng lực kinh doanh của Chi nhánh; hồ sơ không bị HSC trả lại để chỉnh sửa, bổ sung.',100.0,100.0,100.0),
  ('00183881','KHTH-02','KHTH','Phối hợp với các Phòng xây dựng KHKD của Chi nhánh, gửi HSC đúng thời hạn kỳ quý','Hàng quý','Hồ sơ KHKD quý được gửi HSC đúng/trước thời hạn quy định của từng quý.','Chỉ tiêu quý khớp với định hướng KHKD năm đã duyệt, số liệu chính xác, không phải điều chỉnh lại sau khi gửi.',100.0,70.0,70.0),
  ('00183881','KHTH-03','KHTH','Thực hiện giao KHKD cho các phòng nghiệp vụ theo đúng tiến độ kỳ năm','Hàng năm','Hoàn thành giao chỉ tiêu KHKD năm cho các phòng nghiệp vụ trong vòng 5 ngày làm việc kể từ khi Chi nhánh nhận KHKD được HSC phê duyệt.','Chỉ tiêu giao cho từng phòng đầy đủ, khớp tổng thể với KHKD Chi nhánh đã duyệt; phân bổ hợp lý theo năng lực, địa bàn từng phòng, không phát sinh khiếu nại/điều chỉnh.',100.0,100.0,100.0),
  ('00183881','KHTH-04','KHTH','Thực hiện giao KHKD cho các phòng nghiệp vụ theo đúng tiến độ kỳ quý','Hàng quý','Hoàn thành giao chỉ tiêu KHKD quý cho các phòng nghiệp vụ trong vòng 3 ngày làm việc kể từ khi có KHKD quý được duyệt.','Chỉ tiêu giao quý phù hợp tiến độ thực hiện kế hoạch năm, chính xác, không phải điều chỉnh lại.',100.0,70.0,70.0),
  ('00183881','KHTH-05','KHTH','Tham mưu đề xuất các giải pháp điều hành thực hiện nhiệm vụ kinh doanh','Khi phát sinh','Đề xuất được xây dựng và trình Ban Giám đốc trong vòng 2-3 ngày làm việc kể từ khi phát sinh yêu cầu/vấn đề cần tham mưu.','Giải pháp có căn cứ số liệu, phân tích rõ nguyên nhân, khả thi và phù hợp thực tế kinh doanh; được Ban Giám đốc phê duyệt/thông qua.',100.0,100.0,100.0),
  ('00183881','KHTH-06','KHTH','Rà soát, điều chỉnh KHKD của Chi nhánh gửi Trụ sở chính','Khi phát sinh','Hoàn thành rà soát, trình HSC phê duyệt điều chỉnh trong vòng 3-5 ngày làm việc kể từ khi có yêu cầu/căn cứ điều chỉnh.','Số liệu điều chỉnh chính xác, có cơ sở thuyết minh rõ ràng, được HSC phê duyệt ngay lần trình đầu, không phải làm lại.',100.0,100.0,100.0),
  ('00183881','KHTH-07','KHTH','Rà soát, điều chỉnh KHKD các Phòng tại Chi nhánh','Khi phát sinh','Hoàn thành rà soát và ban hành điều chỉnh KHKD cho các Phòng trong vòng 3 ngày làm việc kể từ khi có căn cứ điều chỉnh.','Chỉ tiêu điều chỉnh hợp lý, khớp với KHKD Chi nhánh, được các Phòng đồng thuận thực hiện, không phát sinh khiếu nại.',70.0,70.0,70.0),
  ('00183881','KHTH-08','KHTH','Đo lường, phân tích, báo cáo hiệu quả kinh doanh đa chiều. Rà soát, kiểm soát, đề xuất gia tăng nguồn thu','Khi phát sinh','Báo cáo phân tích và đề xuất được hoàn thành đúng thời hạn theo yêu cầu/chỉ đạo của Ban Giám đốc.','Phân tích đa chiều, đúng trọng tâm, chỉ ra rõ nguyên nhân biến động hiệu quả kinh doanh; giải pháp/đề xuất gia tăng nguồn thu khả thi và được áp dụng vào thực tế.',70.0,70.0,70.0),
  ('00183881','KHTH-09','KHTH','Xây dựng tiêu chí, ban hành thông báo hướng dẫn xét HTNV tập thể và cá nhân tại chi nhánh','Khi phát sinh','Văn bản tiêu chí, hướng dẫn xét HTNV được ban hành trước thời điểm bắt đầu kỳ đánh giá tối thiểu 5 ngày làm việc.','Tiêu chí rõ ràng, minh bạch, phù hợp quy định của HSC và thực tế Chi nhánh; không phải sửa đổi, bổ sung trong quá trình áp dụng.',100.0,100.0,100.0),
  ('00183881','KHTH-10','KHTH','Thực hiện xét HTNV tập thể và cá nhân kỳ Năm','Hàng năm','Hoàn thành xét và công bố kết quả HTNV năm đúng thời hạn theo lịch của HSC/Chi nhánh.','Kết quả xét chính xác, công bằng, đúng tiêu chí đã ban hành; không có khiếu nại hoặc phải xét/điều chỉnh lại.',100.0,100.0,100.0),
  ('00183881','KHTH-11','KHTH','Thực hiện xét HTNV tập thể và cá nhân Quý','Hàng quý','Hoàn thành xét và công bố kết quả HTNV quý đúng thời hạn quy định của từng quý.','Kết quả xét chính xác, đúng tiêu chí, khớp số liệu HTNV thực tế; không có khiếu nại.',70.0,70.0,70.0),
  ('00183881','KHTH-12','KHTH','Thực hiện chấm điểm đánh giá HTNV chi nhánh, điểm xếp hạng chi nhánh kỳ Năm','Hàng năm','Hoàn thành chấm điểm, tổng hợp điểm xếp hạng Chi nhánh và gửi HSC đúng thời hạn kỳ năm.','Điểm số chấm chính xác, đúng phương pháp/quy định của HSC; số liệu khớp với báo cáo HTNV, không bị HSC yêu cầu rà soát lại.',100.0,100.0,100.0),
  ('00183881','KHTH-13','KHTH','Thực hiện chấm điểm đánh giá HTNV chi nhánh, điểm xếp hạng chi nhánh Đánh giá kỳ Quý','Hàng quý','Hoàn thành chấm điểm, tổng hợp điểm xếp hạng Chi nhánh và gửi HSC đúng thời hạn kỳ quý.','Điểm số chấm chính xác, khớp số liệu HTNV quý, đúng quy định; không bị yêu cầu điều chỉnh.',70.0,70.0,70.0),
  ('00183881','KHTH-14','KHTH','Phối hợp trong công tác xếp hạng phòng giao dịch kỳ năm','Hàng năm','Cung cấp số liệu, phối hợp hoàn thành xếp hạng PGD kỳ năm đúng thời hạn quy định.','Số liệu cung cấp chính xác, đầy đủ; kết quả xếp hạng phản ánh đúng thực tế hoạt động của PGD, không có khiếu nại.',70.0,70.0,70.0),
  ('00183881','KHTH-15','KHTH','Phối hợp trong công tác xếp hạng phòng giao dịch kỳ quý','Hàng quý','Cung cấp số liệu, phối hợp hoàn thành xếp hạng PGD kỳ quý đúng thời hạn quy định.','Số liệu chính xác, đầy đủ, kịp thời; kết quả xếp hạng không phải điều chỉnh lại.',70.0,70.0,70.0),
  ('00183881','KHTH-16','KHTH','Phối hợp trong công tác xếp hạng phòng giao dịch kỳ tháng','Hàng tháng','Cung cấp số liệu, phối hợp hoàn thành xếp hạng PGD kỳ tháng đúng thời hạn quy định (trước ngày quy định của tháng sau).','Số liệu chính xác, đầy đủ, không có sai sót ảnh hưởng đến kết quả xếp hạng.',70.0,70.0,70.0),
  ('00183881','KHTH-17','KHTH','Báo cáo kết quả hoạt động kinh doanh Chi nhánh hàng ngày','Hàng ngày','Báo cáo được gửi trước thời điểm quy định trong ngày làm việc kế tiếp (theo quy định nội bộ về báo cáo ngày).','Số liệu khớp đúng với hệ thống nguồn (core banking/báo cáo quản trị); không phải đính chính, báo cáo lại.',10.0,10.0,10.0),
  ('00183881','KHTH-18','KHTH','Báo cáo kết quả hoạt động kinh doanh Chi nhánh hàng tháng','Hàng tháng','Báo cáo được gửi đúng/trước hạn quy định của tháng (thường trong 2-3 ngày làm việc đầu tháng sau).','Số liệu chính xác, đầy đủ nội dung theo mẫu quy định, khớp với báo cáo ngày lũy kế trong tháng; không phải điều chỉnh lại.',70.0,70.0,70.0),
  ('00183881','KHTH-19','KHTH','Báo cáo kết quả hoạt động kinh doanh Chi nhánh hàng quý/6 tháng/năm','Hàng quý','Báo cáo được gửi đúng thời hạn quy định của từng kỳ (quý/6 tháng/năm).','Số liệu chính xác, đầy đủ, có phân tích đánh giá kèm theo; khớp số liệu giữa các kỳ báo cáo, không phải báo cáo lại.',100.0,100.0,100.0),
  ('00183881','KHTH-20','KHTH','Báo cáo tình hình hoạt động của các phòng nghiệp vụ hàng tháng','Hàng tháng','Tổng hợp và gửi báo cáo đúng hạn quy định hàng tháng.','Nội dung phản ánh đầy đủ, chính xác tình hình hoạt động từng phòng nghiệp vụ; số liệu khớp với báo cáo KQKD tháng.',40.0,40.0,40.0),
  ('00183881','KHTH-21','KHTH','Thu thập thông tin địa bàn, chính sách giá phí của đối thủ cạnh tranh định kỳ 6 tháng/lần','Bán niên','Hoàn thành thu thập, tổng hợp thông tin trong kỳ 6 tháng theo lịch công tác.','Thông tin đầy đủ, cập nhật, có nguồn xác thực (khảo sát thực tế/công bố chính thức); có giá trị tham khảo phục vụ hoạch định chính sách giá, phí của Chi nhánh.',100.0,100.0,100.0),
  ('00183881','KHTH-22','KHTH','Báo cáo thống kê thông tư 11 kỳ quý','Hàng quý','Báo cáo được gửi đúng thời hạn quy định của Thông tư 11 theo kỳ quý.','Số liệu thống kê chính xác, đúng biểu mẫu quy định tại Thông tư 11; không bị yêu cầu đính chính.',10.0,10.0,10.0),
  ('00183881','KHTH-23','KHTH','Báo cáo thống kê thông tư 11 kỳ tháng','Hàng tháng','Báo cáo được gửi đúng thời hạn quy định của Thông tư 11 theo kỳ tháng.','Số liệu thống kê chính xác, đúng biểu mẫu quy định; không bị yêu cầu đính chính, báo cáo lại.',10.0,10.0,10.0),
  ('00183881','KHTH-24','KHTH','Báo cáo đột xuất theo yêu cầu của Lãnh đạo Chi nhánh, Trụ sở chính có Độ phức tạp rất cao','Khi phát sinh','Hoàn thành và trình báo cáo trong vòng tối đa 5 ngày làm việc kể từ khi nhận yêu cầu.','Nội dung đáp ứng đầy đủ, đúng trọng tâm yêu cầu của Lãnh đạo; số liệu, phân tích chính xác, không phải chỉnh sửa, bổ sung nhiều lần.',100.0,100.0,100.0),
  ('00183881','KHTH-25','KHTH','Báo cáo đột xuất theo yêu cầu của Lãnh đạo Chi nhánh, Trụ sở chính có Độ phức tạp cao','Khi phát sinh','Hoàn thành và trình báo cáo trong vòng tối đa 3 ngày làm việc kể từ khi nhận yêu cầu.','Nội dung đáp ứng đầy đủ yêu cầu, số liệu chính xác; không phải chỉnh sửa, bổ sung nhiều lần.',70.0,70.0,70.0),
  ('00183881','KHTH-26','KHTH','Báo cáo đột xuất theo yêu cầu của Lãnh đạo Chi nhánh, Trụ sở chính có Độ phức tạp trung bình','Khi phát sinh','Hoàn thành và trình báo cáo trong vòng tối đa 2 ngày làm việc kể từ khi nhận yêu cầu.','Nội dung đầy đủ, chính xác theo yêu cầu; không phải chỉnh sửa lại.',40.0,40.0,40.0),
  ('00183881','KHTH-27','KHTH','Báo cáo đột xuất theo yêu cầu của Lãnh đạo Chi nhánh, Trụ sở chính có Độ phức tạp thấp','Khi phát sinh','Hoàn thành và trình báo cáo trong vòng 1 ngày làm việc kể từ khi nhận yêu cầu.','Nội dung đáp ứng đúng yêu cầu, số liệu chính xác, không có sai sót.',10.0,10.0,10.0),
  ('00183881','KHTH-28','KHTH','Báo cáo ngoại ngành có Độ phức tạp rất cao','Khi phát sinh','Hoàn thành và gửi báo cáo trong vòng tối đa 5 ngày làm việc kể từ khi nhận yêu cầu của cơ quan/đơn vị ngoại ngành.','Nội dung, số liệu đáp ứng đầy đủ, đúng yêu cầu của cơ quan ngoại ngành; không bị yêu cầu bổ sung, chỉnh sửa nhiều lần.',100.0,100.0,100.0),
  ('00183881','KHTH-29','KHTH','Báo cáo ngoại ngành có Độ phức tạp cao','Khi phát sinh','Hoàn thành và gửi báo cáo trong vòng tối đa 3 ngày làm việc kể từ khi nhận yêu cầu.','Nội dung, số liệu đầy đủ, chính xác, đúng yêu cầu; không bị trả lại yêu cầu bổ sung.',70.0,70.0,70.0),
  ('00183881','KHTH-30','KHTH','Báo cáo ngoại ngành có Độ phức tạp trung bình','Khi phát sinh','Hoàn thành và gửi báo cáo trong vòng tối đa 2 ngày làm việc kể từ khi nhận yêu cầu.','Nội dung, số liệu đầy đủ, chính xác theo yêu cầu.',40.0,40.0,40.0),
  ('00183881','KHTH-31','KHTH','Báo cáo ngoại ngành có Độ phức tạp thấp','Khi phát sinh','Hoàn thành và gửi báo cáo trong vòng 1 ngày làm việc kể từ khi nhận yêu cầu.','Nội dung, số liệu đầy đủ, chính xác, không có sai sót.',10.0,10.0,10.0),
  ('00183881','KHTH-32','KHTH','Trình, ban hành văn bản triển khai công tác đánh giá cán bộ, hướng dẫn thực hiện trên PM tại đơn vị','Khi phát sinh','Văn bản được trình, ban hành trước khi kỳ đánh giá bắt đầu tối thiểu 5 ngày làm việc.','Nội dung hướng dẫn đầy đủ, rõ ràng, đúng quy định của HSC; dễ thực hiện trên hệ thống PM, không phải sửa đổi, bổ sung nhiều lần.',100.0,70.0,70.0),
  ('00183881','KHTH-33','KHTH','Trình ban hành mới Bộ chỉ tiêu BSC phòng, KPIs cán bộ áp dụng tại đơn vị','Khi phát sinh','Bộ chỉ tiêu được xây dựng, trình ban hành đúng thời hạn theo kế hoạch/chỉ đạo của HSC và Chi nhánh.','Chỉ tiêu BSC/KPIs xây dựng phù hợp với KHKD, chức năng nhiệm vụ từng vị trí; được phê duyệt và áp dụng ổn định, không phải điều chỉnh nhiều lần trong kỳ áp dụng.',100.0,70.0,70.0),
  ('00183881','KHTH-34','KHTH','Trình điều chỉnh, cập nhật Bộ chỉ tiêu BSC phòng, KPIs cán bộ áp dụng tại đơn vị','Khi phát sinh','Hoàn thành trình điều chỉnh, cập nhật trong vòng 3-5 ngày làm việc kể từ khi có căn cứ điều chỉnh.','Nội dung điều chỉnh có căn cứ hợp lý, phù hợp thực tế phát sinh; được phê duyệt ngay lần trình đầu.',10.0,10.0,10.0),
  ('00183881','KHTH-35','KHTH','Thực hiện quy trình ĐGCB trên PS kỳ Quý','Hàng quý','Hoàn thành quy trình đánh giá cán bộ trên hệ thống PS đúng thời hạn quy định của kỳ quý.','Dữ liệu đánh giá đầy đủ, chính xác, khớp đúng thực tế thực hiện nhiệm vụ của cán bộ; không phải chỉnh sửa lại trên hệ thống.',100.0,70.0,70.0),
  ('00183881','KHTH-36','KHTH','Thực hiện quy trình ĐGCB trên PS kỳ 6 tháng/năm','Bán niên','Hoàn thành quy trình đánh giá cán bộ trên hệ thống PS đúng thời hạn quy định của kỳ 6 tháng/năm.','Dữ liệu đánh giá đầy đủ, chính xác, phản ánh đúng kết quả thực hiện nhiệm vụ; không phải chỉnh sửa lại.',100.0,100.0,100.0),
  ('00183881','KHTH-37','KHTH','Phối hợp rà soát dữ liệu đánh giá cán bộ các vị trí tác nghiệp, TDS...','Hàng quý','Hoàn thành rà soát và phản hồi dữ liệu đúng thời hạn quy định trong quý.','Dữ liệu rà soát chính xác, đầy đủ; phát hiện và xử lý kịp thời các sai lệch, chênh lệch dữ liệu giữa hệ thống và thực tế.',10.0,10.0,10.0),
  ('00183881','TK-01','Thư ký','Tổng hợp nội dung trình phê duyệt kết quả TĐ hàng quý/6 tháng/năm','Khi phát sinh','Tổng hợp và trình phê duyệt kết quả thi đua đúng thời hạn quy định của từng kỳ (quý/6 tháng/năm).','Nội dung tổng hợp đầy đủ, chính xác, khớp với số liệu HTNV/xét thi đua; được phê duyệt ngay lần trình đầu, không phải chỉnh sửa lại.',100.0,100.0,100.0),
  ('00183881','TK-02','Thư ký','Tổng hợp nội dung Thông báo kết luận họp giao ban/họp chuyên đề','Khi phát sinh','Thông báo kết luận được ban hành trong vòng 1-2 ngày làm việc kể từ khi kết thúc cuộc họp.','Nội dung phản ánh đúng, đầy đủ ý kiến chỉ đạo, kết luận của cuộc họp; không có sai sót hoặc khiếu nại từ các bên liên quan.',70.0,70.0,70.0),
  ('00183881','TK-03','Khác','Theo dõi cơ chế động lực của HSC','Hàng quý','Cập nhật, tổng hợp thông tin về cơ chế động lực đúng thời hạn theo quý.','Thông tin cập nhật đầy đủ, chính xác, kịp thời; được áp dụng đúng cho Chi nhánh, không bỏ sót cơ chế mới ban hành.',7.0,10.0,10.0),
  ('00183881','TK-04','Khác','Ban hành văn bản phát động thi đua tại Chi nhánh','Bán niên','Văn bản phát động thi đua được ban hành trước khi bắt đầu kỳ thi đua (đầu kỳ 6 tháng).','Nội dung phát động phù hợp mục tiêu KHKD của Chi nhánh trong kỳ, rõ ràng, dễ triển khai; được phổ biến đầy đủ tới toàn bộ các phòng/PGD.',100.0,70.0,70.0),
  ('00183881','TK-05','Khác','Thực hiện khen thưởng tới các phòng nghiệp vụ','Hàng quý','Hoàn thành xét, thực hiện khen thưởng đúng thời hạn trong kỳ quý theo kế hoạch/quy định.','Khen thưởng đúng đối tượng, đúng tiêu chí đã ban hành; không có khiếu nại hoặc phải điều chỉnh lại kết quả.',10.0,10.0,10.0),
  ('00183881','TK-06','Khác','Theo dõi rà soát công tác gán AM RM của các phòng nghiệp vụ','Hàng tuần','Hoàn thành rà soát, cập nhật thông tin gán AM/RM đúng hạn theo tuần.','Dữ liệu gán AM/RM chính xác, cập nhật kịp thời theo biến động thực tế; không có sai sót, trùng lặp hoặc bỏ sót khách hàng.',10.0,10.0,10.0),
  ('00183881','TK-07','Khác','Công tác tham gia ý kiến có Độ phức tạp rất cao','Khi phát sinh','Ý kiến tham gia được hoàn thành, phản hồi trong vòng tối đa 5 ngày làm việc kể từ khi nhận yêu cầu.','Ý kiến có căn cứ, phân tích đầy đủ các khía cạnh liên quan; được đơn vị đề nghị chấp thuận, không phải bổ sung/chỉnh sửa nhiều lần.',10.0,10.0,10.0),
  ('00183881','TK-08','Khác','Công tác tham gia ý kiến có Độ phức tạp cao','Khi phát sinh','Ý kiến tham gia được hoàn thành, phản hồi trong vòng tối đa 3 ngày làm việc kể từ khi nhận yêu cầu.','Ý kiến có căn cứ, đầy đủ nội dung theo yêu cầu; không phải bổ sung, chỉnh sửa nhiều lần.',7.0,7.0,7.0),
  ('00183881','TK-09','Khác','Công tác tham gia ý kiến có Độ phức tạp trung bình','Khi phát sinh','Ý kiến tham gia được hoàn thành, phản hồi trong vòng tối đa 2 ngày làm việc kể từ khi nhận yêu cầu.','Ý kiến đầy đủ, chính xác, đáp ứng đúng yêu cầu.',4.0,4.0,4.0),
  ('00183881','TK-10','Khác','Công tác tham gia ý kiến có Độ phức tạp thấp','Khi phát sinh','Ý kiến tham gia được hoàn thành, phản hồi trong vòng 1 ngày làm việc kể từ khi nhận yêu cầu.','Ý kiến đúng, đầy đủ nội dung theo yêu cầu, không có sai sót.',1.0,1.0,1.0),
  ('00183881','TK-11','Khác','Công tác khác có Độ phức tạp rất cao','Khi phát sinh','Hoàn thành công việc trong vòng tối đa 5 ngày làm việc kể từ khi phát sinh/được giao.','Kết quả công việc đáp ứng đầy đủ, đúng yêu cầu; không phải làm lại hoặc bổ sung nhiều lần.',10.0,10.0,10.0),
  ('00183881','TK-12','Khác','Công tác khác có Độ phức tạp cao','Khi phát sinh','Hoàn thành công việc trong vòng tối đa 3 ngày làm việc kể từ khi phát sinh/được giao.','Kết quả công việc đầy đủ, chính xác theo yêu cầu; không phải làm lại.',7.0,7.0,7.0),
  ('00183881','TK-13','Khác','Công tác khác có Độ phức tạp trung bình','Khi phát sinh','Hoàn thành công việc trong vòng tối đa 2 ngày làm việc kể từ khi phát sinh/được giao.','Kết quả công việc đầy đủ, chính xác, đáp ứng yêu cầu.',4.0,4.0,4.0),
  ('00183881','TK-14','Khác','Công tác khác có Độ phức tạp thấp','Khi phát sinh','Hoàn thành công việc trong vòng 1 ngày làm việc kể từ khi phát sinh/được giao.','Kết quả công việc đúng yêu cầu, không có sai sót.',1.0,1.0,1.0),
  ('00157761','HC-VT-01','Công tác văn thư','Quản lý, sử dụng con dấu của Chi nhánh theo đúng quy định (sổ theo dõi bàn giao, đóng dấu đúng thẩm quyền, đúng văn bản)','Phát sinh (theo yêu cầu phát sinh hàng ngày)','Ngay khi có yêu cầu','Đúng quy định, đúng thẩm quyền, có sổ theo dõi',10.0,4.0,1.0),
  ('00157761','HC-VT-02','Công tác văn thư','Đầu mối tiếp nhận công văn đi, công văn đến (kể cả thư bảo lãnh); mở sổ theo dõi','Hàng ngày','Trong ngày','Sổ theo dõi đầy đủ, chính xác',7.0,4.0,4.0),
  ('00157761','HC-VT-03','Công tác văn thư','Thực hiện thủ tục chuyển phát văn bản đến đúng nơi quy định (VPĐT, dịch vụ chuyển phát, trình lãnh đạo phê duyệt)','Hàng ngày','Trong ngày hoặc theo yêu cầu','Đúng nơi nhận, đúng thời hạn',10.0,4.0,4.0),
  ('00157761','HC-VT-04','Công tác văn thư','Đầu mối tiếp nhận thư, chuyển phát nhanh từ các đơn vị dịch vụ và chuyển đến đúng nơi theo yêu cầu','Hàng ngày','Trong ngày','Chuyển, nhận đúng đối tượng',7.0,4.0,4.0),
  ('00157761','HC-VT-05','Công tác văn thư','Thực hiện lưu trữ văn bản đi, đến đúng quy định','Hàng ngày','Trong ngày','Đảm bảo đầy đủ, dễ tra cứu',7.0,4.0,4.0),
  ('00157761','HC-TS-01','Quản lý & sử dụng TS, CCLĐ','Đầu mối phối hợp các bộ phận liên quan xây dựng kế hoạch tài sản, đề xuất chủ trương mua sắm tài sản, công cụ của Chi nhánh hàng năm','Hàng quý (xây dựng/rà soát kế hoạch Tháng/Quý/Năm)','Tháng/Quý/Năm','Đáp ứng yêu cầu của Chi nhánh, được Ban lãnh đạo phê duyệt về nội dung',10.0,10.0,10.0),
  ('00157761','HC-TS-02','Quản lý & sử dụng TS, CCLĐ','Đầu mối rà soát, đề xuất chủ trương, phối hợp các bộ phận liên quan thực hiện mua sắm công cụ theo kế hoạch và đề xuất của các đơn vị','Phát sinh','Thời gian theo quy định trình tự mua sắm TS, CCLĐ','Đầy đủ hồ sơ và nội dung theo đúng quy định về quản lý, mua sắm TS, CCLĐ',10.0,10.0,10.0),
  ('00157761','HC-TS-03','Quản lý & sử dụng TS, CCLĐ','Quản lý, thống kê hiện vật TSCĐ, CCLĐ của Phòng và Chi nhánh; phối hợp bộ phận IT, kế toán đánh mã tài sản, điều chuyển, ghi sổ theo dõi, phân bổ sử dụng, xuất/nhập kho','Hàng tuần','Thường xuyên','Chính xác số liệu, đảm bảo cân đối giữa sổ sách và thực tế',4.0,7.0,4.0),
  ('00157761','HC-TS-04','Quản lý & sử dụng TS, CCLĐ','Đầu mối phối hợp với các đơn vị liên quan đề xuất tổ chức thanh lý tài sản cố định, công cụ lao động','Phát sinh','Thời gian theo quy định trình tự','Đầy đủ hồ sơ và nội dung theo đúng quy định',10.0,10.0,10.0),
  ('00157761','HC-TS-05','Quản lý & sử dụng TS, CCLĐ','Đề xuất và triển khai thủ tục sửa chữa tài sản cố định, công cụ lao động','Phát sinh (Quý/Năm)','Quý/Năm hoặc thời gian theo quy định trình tự','Hợp lý, hiệu quả; đầy đủ hồ sơ, đúng quy định, được Ban lãnh đạo phê duyệt',7.0,7.0,10.0),
  ('00157761','HC-TS-06','Quản lý & sử dụng TS, CCLĐ','Triển khai các thủ tục kiểm kê TS, CCLĐ','hàng năm',NULL,NULL,10.0,7.0,10.0),
  ('00157761','HC-TS-07','Quản lý & sử dụng TS, CCLĐ','Theo dõi quản lý TS,CCLĐ theo đúng quy định, đảm bảo cân đối giữa sổ sách và thực tế','Thường xuyên',NULL,NULL,4.0,7.0,4.0),
  ('00157761','HC-TS-08','Quản lý & sử dụng TS, CCLĐ','Đánh giá hiện trạng TS, CCLĐ, đề xuất biện pháp xử lý sau đánh giá','Tối thiểu 1 năm/lần',NULL,NULL,7.0,10.0,10.0),
  ('00157761','HC-TS-09','Quản lý & sử dụng TS, CCLĐ','Thực hiện các báo cáo theo yêu cầu của lãnh đạo','Theo yêu cầu lãnh đạo',NULL,NULL,7.0,7.0,7.0),
  ('00157761','HC-TS-10','Quản lý & sử dụng TS, CCLĐ','Thực hiện các thủ tục thanh toán các chi phí liên quan tới thuê mua TS','Tháng/Quý/Năm',NULL,NULL,7.0,7.0,7.0),
  ('00157761','HC-TS-11','Quản lý & sử dụng TS, CCLĐ','Thực hiện tốt nhiệm vụ tại các Tổ mua sắm, nghiệm thu, tổ thẩm định theo quyết định của Giám đốc','Đúng thời gian theo yêu cầu',NULL,NULL,7.0,10.0,10.0),
  ('00157761','HC-DV-1','Thuê dịch vụ phục vụ hoạt  động KD','Thực hiện các thủ tục thuê Phòng giao dịch, thuê an ninh, bảo vệ, thuê xe ô tô.......','hàng năm',NULL,NULL,10.0,10.0,10.0),
  ('00157761','HC-DV-2','Thuê dịch vụ phục vụ hoạt  động KD','Thực hiện các thủ tục thanh toán các chi phí liên quan tới thuê dịch vụ','Tháng/Quý/Năm',NULL,NULL,7.0,7.0,7.0),
  ('00157761','HC-VPP-1','Văn phòng phẩm & ấn chỉ','Thực hiện các thủ tục mua sắm VPP và Ấn chỉ thường theo kế hoạch và theo phát sinh được Ban lãnh đạo phê duyệt','Kịp thời theo yêu cầu của các phòng',NULL,NULL,7.0,7.0,10.0),
  ('00157761','HC-VPP-2','Văn phòng phẩm & ấn chỉ','Theo dõi và quản lý kho ấn chỉ đảm bảo cân đối giữa sổ sách và thực tế','Thường xuyên',NULL,NULL,4.0,7.0,7.0),
  ('00157761','HC-VPP-3','Văn phòng phẩm & ấn chỉ','Thực hiện các thủ tục giao nhận đúng quy định và lưu đầy đủ hồ sơ liên quan','Ngay khi giao nhận',NULL,NULL,7.0,4.0,4.0),
  ('00157761','HC-VPP-4','Văn phòng phẩm & ấn chỉ','Thực hiện thanh toán các chi phí liên quan tới VPP, Ấn chỉ thường','Tháng/Quý',NULL,NULL,7.0,4.0,7.0),
  ('00157761','HC-VPP-5','Văn phòng phẩm & ấn chỉ','Chủ động và phối hợp tốt trong công tác đánh giá hiệu quả sử dụng VPP và Ấn chỉ thường','Tối thiểu 1 năm/lần',NULL,NULL,7.0,7.0,7.0),
  ('00157761','HC-VPP-6','Văn phòng phẩm & ấn chỉ','Thực hiện báo cáo và phối hợp báo cáo theo yêu cầu của lãnh đạo','Theo yêu cầu',NULL,NULL,7.0,7.0,7.0),
  ('00157761','HC-HC-1','Chi tiêu hành chính','Thực hiện các thủ tục tạm ứng và hoàn tạm ứng đúng quy định','Đúng thời gian',NULL,NULL,4.0,7.0,10.0),
  ('00157761','HC-HC-2','Chi tiêu hành chính','Thực hiện chi tiêu theo quy định','Kịp thời',NULL,NULL,4.0,4.0,10.0),
  ('00157761','HC-CP-1','Chi phí thường xuyên','Thực hiện thanh toán các chi phí thường xuyên (điện, nước, internet, điện thoại...)','Hàng tháng',NULL,NULL,7.0,7.0,7.0),
  ('00157761','HC-TH-1','Nhận diện thương hiệu','Phối hợp thực hiện các bảng, biển, decal đảm bảo theo nhận diện thương hiệu (không bao gồm các gói thầu liên quan tới tuân thủ nhận diện thương hiệu và KGGD của BIDV)','Theo yêu cầu các phòng, HO',NULL,NULL,7.0,7.0,10.0),
  ('00157761','HC-TH-2','Nhận diện thương hiệu','Thanh quyết toán các khoản chi tiêu theo quy định','Đúng quy định',NULL,NULL,7.0,7.0,10.0),
  ('00157761','HC-PCCC-1','PCCC & An ninh','Có kế hoạch, phương án đảm bảo an ninh, an toàn đối với người và tài sản của Chi nhánh và thực hiện các báo cáo liên quan.','Năm',NULL,NULL,7.0,7.0,10.0),
  ('00157761','HC-PCCC-2','PCCC & An ninh','Phối hợp với chính quyền địa phương, đối tác về dịch vụ an ninh (công an, công ty cung cấp dịch vụ an ninh bảo vệ...) đảm bảo an toàn nơi làm việc (trụ sở chính và các PGD) và công tác vận chuyển tài sản có giá theo quy định của BIDV','Kịp thời, thường xuyên',NULL,NULL,7.0,10.0,10.0),
  ('00157761','HC-PCCC-3','PCCC & An ninh','Có kế hoạch, phương án đảm bảo PCCC theo đúng quy định về an toàn PCCC tại Trụ sở chi nhánh và các PGD.','Năm',NULL,NULL,7.0,7.0,10.0),
  ('00157761','HC-PCCC-4','PCCC & An ninh','Triển khai công tác PCCC tại chi nhánh (diễn tập, đào tạo, truyền thông, quán triệt…tới các tập thể và cá nhân thuộc Chi nhánh)','Theo kế hoạch',NULL,NULL,7.0,7.0,10.0),
  ('00157761','HC-PCCC-5','PCCC & An ninh','Phối hợp với các phòng nghiệp vụ, các đơn vị chức năng về PCCC đảm bảo hồ sơ PCCC đầy đủ, đúng quy định và các báo cáo liên quan.','Kịp thời, Theo quy định',NULL,NULL,7.0,7.0,10.0),
  ('00157761','HC-PCCC-6','PCCC & An ninh','Có kế hoạch thực hiện công tác Quốc phòng tuân thủ theo quy định của nhà nước.','Năm',NULL,NULL,7.0,7.0,7.0),
  ('00157761','HC-PCCC-7','PCCC & An ninh','Tổ chức thực hiện hoặc phối hợp thực hiện công tác an ninh quốc phòng, dân quân tự vệ, quân nhân tại đơn vị và các báo cáo liên quan.','Theo yêu cầu của cơ quan quân đội',NULL,NULL,7.0,7.0,7.0),
  ('00157761','HC-PCCC-8','PCCC & An ninh','Lưu hồ sơ theo quy định','Ngay khi kết thúc công việc',NULL,NULL,4.0,4.0,4.0)
) as v(ma_cbnv, ma_cv, nhom_nv, ten_cong_viec, dinh_ky, tc_td, tc_cl, a, b, c)
